for (int i = 0; i < size; i++) {
    TreeNode* node = new TreeNode(values[i], freqs[i]);
    queue.push(std::make_pair(freqs[i], node));
}
while (queue.size() > 1) {
    std::pair<double, TreeNode*> left = queue.top();
    queue.pop();
    std::pair<double, TreeNode*> right = queue.top();
    queue.pop();
    TreeNode* newNode = new TreeNode(0, left.first + right.first);
    newNode->left = left.second;
    newNode->right = right.second;
    queue.push(std::make_pair(newNode->freq, newNode));
}
return queue.top().second;

